package com.stratum.domain.workout.myorep

import com.stratum.domain.program.SetType
import com.stratum.domain.workout.SetSlot
import com.stratum.domain.workout.isAutoGeneratedMyoMini

/**
 * Pure structure helpers for Myo-Rep Match blocks.
 *
 * A contiguous run of non-mini [MyoRepKind.RepMatching] slots is one match block:
 * - **Activation** = first non-mini MM in the run
 * - **Match backoffs** = following non-mini MM rows (belong to that activation)
 * Auto-generated minis (`mini-` overlay ids) hang under a match backoff (or floor activation)
 * and do not count as activation/backoff template rows.
 */
object MyoMatchStructure {

    fun isMyoMatchKind(setType: SetType, myoRepKind: MyoRepKind?): Boolean =
        setType == SetType.MyoRep && myoRepKind == MyoRepKind.RepMatching

    fun isMyoMatchKind(slot: SetSlot): Boolean =
        isMyoMatchKind(slot.setType, slot.myoRepKind)

    fun isMyoFloorKind(slot: SetSlot): Boolean =
        slot.setType == SetType.MyoRep &&
            (slot.myoRepKind == MyoRepKind.RepFloor || slot.myoRepKind == null)

    /** Non-mini template/live MM row (activation or match backoff). */
    fun isMyoMatchWorking(slot: SetSlot): Boolean =
        isMyoMatchKind(slot) && !slot.isAutoGeneratedMyoMini()

    /**
     * First non-mini MM in a contiguous match run ending at or containing [index].
     * False for minis and for match backoffs after an earlier MM working set.
     */
    fun isMyoMatchActivation(slots: List<SetSlot>, index: Int): Boolean {
        if (index !in slots.indices) return false
        val slot = slots[index]
        if (!isMyoMatchWorking(slot)) return false
        val prevWorking = previousNonMini(slots, index) ?: return true
        return !isMyoMatchWorking(prevWorking)
    }

    fun isMyoMatchBackoff(slots: List<SetSlot>, index: Int): Boolean {
        if (index !in slots.indices) return false
        val slot = slots[index]
        if (!isMyoMatchWorking(slot)) return false
        return !isMyoMatchActivation(slots, index)
    }

    fun isMyoMatchActivation(slots: List<SetSlot>, slot: SetSlot): Boolean {
        val index = slots.indexOfFirst { it.slotId == slot.slotId }
        return isMyoMatchActivation(slots, index)
    }

    fun isMyoMatchBackoff(slots: List<SetSlot>, slot: SetSlot): Boolean {
        val index = slots.indexOfFirst { it.slotId == slot.slotId }
        return isMyoMatchBackoff(slots, index)
    }

    /**
     * Nearest prior (or self) match activation for [fromIndex].
     * Walks back across minis and match backoffs within the contiguous MM run.
     */
    fun resolveMatchActivation(slots: List<SetSlot>, fromIndex: Int): SetSlot? {
        if (fromIndex !in slots.indices) return null
        val workingIndex = indexOfNearestNonMiniAtOrBefore(slots, fromIndex) ?: return null
        val working = slots[workingIndex]
        if (!isMyoMatchWorking(working)) return null
        return headOfMatchRun(slots, workingIndex)
    }

    fun resolveMatchActivation(slots: List<SetSlot>, from: SetSlot): SetSlot? {
        val index = slots.indexOfFirst { it.slotId == from.slotId }
        return resolveMatchActivation(slots, index)
    }

    /**
     * Contiguous non-mini match backoffs immediately after the activation at [activationIndex].
     */
    fun matchBackoffsAfter(slots: List<SetSlot>, activationIndex: Int): List<SetSlot> {
        if (!isMyoMatchActivation(slots, activationIndex)) return emptyList()
        return slots
            .drop(activationIndex + 1)
            .asSequence()
            .filterNot { it.isAutoGeneratedMyoMini() }
            .takeWhile { isMyoMatchWorking(it) }
            .toList()
    }

    fun matchBackoffCount(slots: List<SetSlot>, activationIndex: Int): Int =
        matchBackoffsAfter(slots, activationIndex).size

    /**
     * Auto-generated minis immediately after [anchor] (activation for floor, match backoff
     * for match), stopping at the next non-mini slot.
     */
    fun contiguousMinisAfter(slots: List<SetSlot>, anchor: SetSlot): List<SetSlot> {
        val actIdx = slots.indexOfFirst { it.slotId == anchor.slotId }
        if (actIdx < 0) return emptyList()
        return slots.drop(actIdx + 1).takeWhile { it.isAutoGeneratedMyoMini() }
    }

    /**
     * Owning cluster anchor for a logged myo slot:
     * - mini → nearest prior non-mini MyoRep (match backoff or floor activation)
     * - match backoff / floor activation → itself
     * - match activation → null (no mini cluster on activation)
     */
    fun resolveClusterAnchor(slots: List<SetSlot>, from: SetSlot): SetSlot? {
        if (from.setType != SetType.MyoRep) return null
        if (from.isAutoGeneratedMyoMini()) {
            val index = slots.indexOfFirst { it.slotId == from.slotId }
            if (index < 0) return null
            return previousNonMini(slots, index)?.takeIf { it.setType == SetType.MyoRep }
        }
        val index = slots.indexOfFirst { it.slotId == from.slotId }
        if (index < 0 || isMyoMatchActivation(slots, index)) return null
        return from
    }

    private fun headOfMatchRun(slots: List<SetSlot>, workingIndex: Int): SetSlot? {
        var j = workingIndex
        var prev = previousNonMiniIndex(slots, j)
        while (prev != null && isMyoMatchWorking(slots[prev])) {
            j = prev
            prev = previousNonMiniIndex(slots, j)
        }
        return slots.getOrNull(j)?.takeIf { isMyoMatchWorking(it) }
    }

    private fun indexOfNearestNonMiniAtOrBefore(slots: List<SetSlot>, fromIndex: Int): Int? {
        var i = fromIndex
        while (i >= 0) {
            if (!slots[i].isAutoGeneratedMyoMini()) return i
            i--
        }
        return null
    }

    private fun previousNonMini(slots: List<SetSlot>, index: Int): SetSlot? {
        val prevIndex = previousNonMiniIndex(slots, index) ?: return null
        return slots[prevIndex]
    }

    private fun previousNonMiniIndex(slots: List<SetSlot>, index: Int): Int? {
        var i = index - 1
        while (i >= 0) {
            if (!slots[i].isAutoGeneratedMyoMini()) return i
            i--
        }
        return null
    }
}
